contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);
        require(amount == 10, "precondition: only test play with 10 wei so pre-call pot is at least 10");

        uint potBefore = c.pot(); if (__ESBMC_reverted()) return;
        uint balBefore = address(this).balance;

        bool reverted;
        c.play{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint balAfter = address(this).balance;
        uint received = balAfter > balBefore ? balAfter - balBefore : 0;

        assert((amount != 10 && reverted) || (amount == 10 && !reverted && received <= potBefore));
    }
}

